#!/usr/bin/env bash
# Compile the Lean generated by an extraction (Types, FunsExternal = the template as-is, Funs) against the pinned,
# already-built Aeneas + Mathlib packages of another worktree on the box (read-only use of its .lake/packages).
# Usage: bash experiments/simd/jobs/lean-check.sh SCRATCH_NAME...   (e.g. simd-x1; reads $HOME/rx/scratch/NAME/lean/Impl)
set -o pipefail
export PATH="$HOME/.elan/bin:$PATH"
pk=""
for c in /data/rx/w/*/lean/.lake/packages; do
  if [ -f "$c/mathlib/.lake/build/lib/lean/Mathlib.olean" ] && [ -f "$c/aeneas/backends/lean/.lake/build/lib/lean/Aeneas.olean" ]; then pk=$c; break; fi
done
[ -n "$pk" ] || { echo "no built package set found"; exit 2; }
LP=""
for p in "$pk"/*; do [ -d "$p/.lake/build/lib/lean" ] && LP="$LP:$p/.lake/build/lib/lean"; done
LP="$LP:$pk/aeneas/backends/lean/.lake/build/lib/lean"
LP=${LP#:}
mkdir -p "$HOME/rx/scratch/simd-lean-proj"; cp lean/lean-toolchain "$HOME/rx/scratch/simd-lean-proj/"
cd "$HOME/rx/scratch/simd-lean-proj" || exit 2
lean --version
fail=0
for w in "$@"; do
  d="$HOME/rx/scratch/$w/lean"
  echo "######## lean check $w"
  cp "$d/Impl/FunsExternal_Template.lean" "$d/Impl/FunsExternal.lean"
  mods="Types FunsExternal Funs"
  if [ -f "$d/Impl/TypesExternal_Template.lean" ]; then
    cp "$d/Impl/TypesExternal_Template.lean" "$d/Impl/TypesExternal.lean"
    mods="TypesExternal $mods"
  fi
  for m in $mods; do
    LEAN_PATH="$LP:$d" lean --root="$d" -o "$d/Impl/$m.olean" "$d/Impl/$m.lean" 2>&1 | head -40
    rc=${PIPESTATUS[0]}
    echo "$m: rc=$rc"
    [ "$rc" -ne 0 ] && fail=1
  done
done
exit $fail
